INSERT INTO event (
    artist_id, title_ko, title_en, region, venue, event_date, description, official_url, approved_yn
)
SELECT
    a.artist_id,
    seed.title_ko,
    LEFT(a.name_en || ' ' || seed.title_en_tail, 200),
    seed.region,
    seed.venue,
    seed.event_date,
    seed.description,
    COALESCE(seed.official_url, a.official_url),
    'Y'
FROM seed
JOIN artist a ON LOWER(a.slug) = seed.slug_key
WHERE a.approved_yn = 'Y'
  AND NOT EXISTS (
      SELECT 1
      FROM event existing
      WHERE existing.artist_id = a.artist_id
        AND existing.title_ko = seed.title_ko
        AND existing.event_date = seed.event_date
  );

